/** Pure, bounded robot-workshop interpreter. No JavaScript source is evaluated. */
export const LIMITS=Object.freeze({nodes:48,depth:3,repeat:8,steps:256});
export const ROBOT_COMMANDS=Object.freeze({forward:'앞으로 한 칸',left:'왼쪽으로 돌기',right:'오른쪽으로 돌기',interact:'집기 · 누르기 · 배달',repeat:'반복 묶음',if:'센서 조건'});
export const SENSORS=Object.freeze({frontClear:'앞이 비었으면',partHere:'여기에 부품이 있으면',switchHere:'여기에 스위치가 있으면',carrying:'상자를 들고 있으면'});
